package app.kinnect.live;
import android.app.*;import android.widget.*;import org.json.*;
/** Explicit consent before spending trial coins; server is authoritative. */
final class LiveGamePass {
 private static final java.util.Set<Activity> pending=java.util.Collections.newSetFromMap(new java.util.WeakHashMap<Activity,Boolean>());
 static void ensure(Activity a,Runnable ready){if(!pending.add(a))return;NativeApi.shared.initialize(a,ServerConfig.DEFAULT_ORIGIN);NativeApi.shared.call("GET","/api/store",null,(state,error,status)->{if(a.isFinishing()||a.isDestroyed()){pending.remove(a);return;}if(error!=null){pending.remove(a);Toast.makeText(a,I18n.t("Chưa kiểm tra được gói Live Game. Hãy thử lại."),Toast.LENGTH_SHORT).show();return;}if(state.optLong("liveGameUntil")>System.currentTimeMillis()){pending.remove(a);ready.run();return;}final String requestId=java.util.UUID.randomUUID().toString();new Sheet(a).setTitle("Live Game").setMessage(I18n.t("490 xu · 30 ngày")+"\n"+I18n.t("Trừ từ ví xu trải nghiệm. Không tự gia hạn.")+"\n\n"+I18n.t("Live trò chuyện và xem Live miễn phí.")).setPositiveButton(I18n.t("Kích hoạt · 490 xu"),(d,w)->{try{NativeApi.shared.call("POST","/api/store/packages/buy",new JSONObject().put("productId","live_game_30").put("priceCoins",490).put("requestId",requestId),(result,err,code)->{if(a.isFinishing()||a.isDestroyed()){pending.remove(a);return;}pending.remove(a);if(err!=null)Toast.makeText(a,I18n.t(code==402?"Chưa đủ 490 xu.":"Chưa kích hoạt được. Hãy kiểm tra lại gói."),Toast.LENGTH_LONG).show();else ready.run();});}catch(Exception e){pending.remove(a);Toast.makeText(a,I18n.t("Chưa kích hoạt được."),Toast.LENGTH_SHORT).show();}}).setNegativeButton(I18n.t("Hủy"),(d,w)->pending.remove(a)).show().setOnCancelListener(d->pending.remove(a));});}
}
